function Shell({children}:{children:React.ReactNode}){
  const path=usePathname(), router=useRouter(); const [open,setOpen]=useState(false),[query,setQuery]=useState(''),[searchOpen,setSearchOpen]=useState(false),[notificationsOpen,setNotificationsOpen]=useState(false),[read,setRead]=useState<string[]>(notificationsSeed.filter(n=>!n.unread).map(n=>n.id));
  const searchRef=useRef<HTMLDivElement>(null), notificationRef=useRef<HTMLDivElement>(null), searchInputRef=useRef<HTMLInputElement>(null);
  const searchResults=useMemo(()=>{const terms=query.toLowerCase().split(/\s+/).filter(Boolean);const pool=terms.length?searchIndex.filter(item=>terms.every(term=>`${item.kind} ${item.title} ${item.meta} ${item.keywords}`.toLowerCase().includes(term))):searchIndex.slice(0,6);return pool.slice(0,6)},[query]);
  const unreadCount=notificationsSeed.filter(n=>!read.includes(n.id)).length;
  useEffect(()=>{function onPointerDown(e:PointerEvent){const target=e.target as Node;if(searchRef.current&&!searchRef.current.contains(target))setSearchOpen(false);if(notificationRef.current&&!notificationRef.current.contains(target))setNotificationsOpen(false)}function onKeyDown(e:KeyboardEvent){if(e.key==='Escape'){setSearchOpen(false);setNotificationsOpen(false)}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true);searchInputRef.current?.focus()}}document.addEventListener('pointerdown',onPointerDown);document.addEventListener('keydown',onKeyDown);return()=>{document.removeEventListener('pointerdown',onPointerDown);document.removeEventListener('keydown',onKeyDown)}},[]);
  function submitSearch(e:FormEvent){e.preventDefault();const destination=searchResults[0]?.href||`/opportunities?search=${encodeURIComponent(query.trim())}`;if(destination){setSearchOpen(false);router.push(destination)}}
  function openResult(href:string){setQuery('');setSearchOpen(false);router.push(href)}
  function openNotification(id:string,href:string){setRead(prev=>prev.includes(id)?prev:[...prev,id]);setNotificationsOpen(false);router.push(href)}
  return <div className="platform-shell">
    <aside className={`sidebar ${open?'sidebar-open':''}`}>
      <div className="side-logo"><Link href="/" className="brand-logo-link sidebar-logo-link"><BrandLockup className="sidebar-brand-lockup" priority /></Link><button aria-label="Close menu" className="mobile-close" onClick={()=>setOpen(false)}><X size={19}/></button></div>
      <nav>{nav.map(({label,href,icon:Icon})=><Link key={label} href={href} className={path===href||path.startsWith(`${href}/`)?'active':''}><Icon size={18}/><span>{label}</span>{label==='Messages'&&<i>1</i>}</Link>)}</nav>
      <div className={`side-upgrade ${path.startsWith('/fasttrack')?'side-fasttrack-current':''}`}><Zap size={19}/><b>Your FastTrack</b><p>20% complete. Next: add performance media.</p><Link href="/fasttrack">Continue <ArrowRight size={14}/></Link></div>
      <Link href="/profile/alex-carter" className="side-person"><Avatar initials="AC"/><div><b>Alex Carter</b><small>Artist / Musician · Pro Silver</small></div><ChevronDown size={15}/></Link>
    </aside>
    {open&&<button aria-label="Close menu" className="sidebar-scrim" onClick={()=>setOpen(false)}/>} 
    <div className="platform-main"><header className="topbar"><button aria-label="Open menu" className="menu-button" onClick={()=>setOpen(true)}><Menu/></button><Link href="/" className="brand-logo-link mobile-topbar-logo"><BrandLockup className="mobile-brand-lockup" /></Link><div className="top-search-wrap" ref={searchRef}><form className="top-search" role="search" onSubmit={submitSearch}><Search size={17}/><input ref={searchInputRef} aria-label="Search people, opportunities, groups, events" placeholder="Search people, opportunities, groups, events..." value={query} onChange={e=>{setQuery(e.target.value);setSearchOpen(true)}} onFocus={()=>setSearchOpen(true)}/><kbd>⌘ K</kbd></form>{searchOpen&&<div className="top-search-results" aria-label="Search results">{searchResults.length?searchResults.map(({kind,title,meta,href,icon:Icon})=><button key={`${kind}-${title}`} onClick={()=>openResult(href)}><span><Icon size={16}/></span><p><b>{title}</b><small>{kind} · {meta}</small></p><ArrowRight size={14}/></button>):<div className="top-search-empty"><Search size={18}/><p><b>No results found</b><small>Try an artist, group, event, or opportunity name.</small></p></div>}</div>}</div><div className="top-actions"><Link className="invite-link" href="/onboarding?invite=1">Invite Member</Link><div className="notification-wrap" ref={notificationRef}><button aria-label={`Notifications${unreadCount?` (${unreadCount} unread)`:''}`} aria-expanded={notificationsOpen} onClick={()=>setNotificationsOpen(!notificationsOpen)}><Bell size={19}/>{unreadCount>0&&<i/>}</button>{notificationsOpen&&<section className="notifications-panel" aria-label="Notifications"><div><p><b>Notifications</b><small>{unreadCount} unread</small></p><button onClick={()=>setRead(notificationsSeed.map(n=>n.id))}>Mark all read</button></div>{notificationsSeed.map(({id,title,meta,href,icon:Icon})=>{const unread=!read.includes(id);return <button key={id} className={unread?'unread':''} onClick={()=>openNotification(id,href)}><span><Icon size={16}/></span><p><b>{title}</b><small>{meta}</small></p>{unread&&<i/>}</button>})}</section>}</div><Link href="/profile/alex-carter" title="My Profile"><Avatar initials="AC"/></Link></div></header><div className="page-wrap">{children}</div></div>
    <nav className="mobile-nav">{nav.slice(0,4).map(({label,href,icon:Icon})=><Link key={label} href={href} className={path===href?'active':''}><Icon size={20}/><span>{label.replace('MLI ','').replace(' & Groups','')}</span></Link>)}</nav>
  </div>
}

type Opportunity = typeof opportunities[number];
type OpportunityAction = 'Apply'|'Interest'|'Introduction'|'Invitation'|'Info'|'Share';
const userMembership='Pro Silver';
const accessRank:{[key:string]:number}={'All Members':0,Fan:0,Free:0,'Fan / Audiophile':1,'Professional+':2,Professional:2,Pro:2,'Pro Silver':2,'Pro Gold':3,'Pro Platinum':4,Premium:4,'VIP / Alliance':5};
function canAccess(item:Opportunity){return (accessRank[userMembership]??0)>=(accessRank[item.access]??0)}
function opportunityAction(item:Opportunity){
  if(item.state==='Invitation') return 'Accept Invitation';
  if(!canAccess(item)) return 'Upgrade to access';
  if(item.category==='Performance') return 'Apply to Perform';
  if(item.category==='Collaboration') return 'Express Interest';
  if(item.category==='Services') return 'Request Info';
  if(item.organizerKind.includes('MLI')||item.access==='Premium'||item.access==='Pro Platinum'||item.access==='VIP / Alliance') return 'Request Introduction';
  return 'Apply';
}
function OpportunityIcon({category,size}:{category:string;size?:number}){if(category==='Performance')return <Mic2 size={size}/>;if(category==='Collaboration')return <Users size={size}/>;if(category==='Crew')return <ImageIcon size={size}/>;if(category==='Services')return <Store size={size}/>;return <BriefcaseBusiness size={size}/>}
function organizerHref(item:Opportunity){return item.organizerId==='music-legacy'?'/community':item.organizerId.includes('-')&&members.some(m=>m.id===item.organizerId)?`/profile/${item.organizerId}`:'/community'}

function OpportunityCard({item,compact=false,saved,applied,onSave,onAction}:{item:Opportunity;compact?:boolean;saved?:boolean;applied?:boolean;onSave?:(id:number)=>void;onAction?:(item:Opportunity,action:OpportunityAction)=>void}){
  const [detail,setDetail]=useState(false); const [why,setWhy]=useState(false); const [share,setShare]=useState(false);
  const action=opportunityAction(item), locked=!canAccess(item);
  function openAction(kind:OpportunityAction){onAction?.(item,kind)}
  return <><article className={`opp-card opportunity-engine-card ${compact?'compact':''} ${item.state==='Invitation'?'invitation-card':''}`}><div className="opp-top"><div><span className="opp-type-icon"><OpportunityIcon category={item.category} size={15}/></span><Badge>{item.category}</Badge><span className="access-type">For {item.lookingFor}</span></div><div className="opp-card-tools"><button aria-label={saved?'Unsave opportunity':'Save opportunity'} className={saved?'saved':''} onClick={()=>onSave?.(item.id)}><Bookmark size={17} fill={saved?'currentColor':'none'}/>{!compact&&<span>{saved?'Saved':'Save'}</span>}</button><button aria-label="Share opportunity" onClick={()=>setShare(!share)}><Share2 size={16}/></button>{share&&<div className="opp-share-menu">{['Copy Link','Share to Member','Share to Group','Send in Message'].map(x=><button key={x} onClick={()=>openAction('Share')}>{x}</button>)}</div>}</div></div><div className="opp-state-row">{[item.state, item.trust, applied?'Applied':''].filter(Boolean).slice(0,3).map((x,i)=><span className={i===0&&item.state==='Closing Soon'?'urgent':''} key={`${x}-${i}`}>{x}</span>)}</div><button className="opp-title-button" onClick={()=>setDetail(true)}><h3>{item.title}</h3></button><Link className="org" href={organizerHref(item)}>{item.organization}</Link><div className="meta-row"><span><MapPin size={13}/>{item.location}</span><span><CalendarDays size={13}/>{item.date}</span><span><CircleDollarSign size={13}/>{item.compensation}</span></div>{!compact&&<p className="opp-desc">{item.summary}</p>}<div className="opp-scarcity"><Clock3 size={13}/><span>{item.closingDays<=3?'Closing soon: ':''}Applications close {item.deadline}</span><small>{item.slots}</small></div><div className="skill-row">{item.skills.slice(0,3).map(skill=><span className={item.matchedSkills.includes(skill)?'matched':''} key={skill}>{item.matchedSkills.includes(skill)?<Check size={11}/>:null}{skill}</span>)}</div><div className="why-inline"><Sparkles/> <b>{item.match}% Match</b><span>{item.reasons[0]}</span></div>{why&&<div className="opp-match-detail">{item.reasons.map(reason=><span key={reason}><Check size={13}/>{reason}</span>)}</div>}<div className="opp-bottom"><button className="text-button" onClick={()=>setWhy(!why)}>Why this matches you <ChevronDown size={14}/></button><button className={locked?'locked-action':'primary-action small-primary'} onClick={()=>locked?openAction('Info'):openAction(action.includes('Interest')?'Interest':action.includes('Introduction')?'Introduction':action.includes('Invitation')?'Invitation':action.includes('Info')?'Info':'Apply')}>{action} <ArrowRight size={14}/></button></div></article>
  {detail&&<OpportunityDetail item={item} saved={Boolean(saved)} applied={Boolean(applied)} onClose={()=>setDetail(false)} onSave={()=>onSave?.(item.id)} onAction={openAction}/>}</>
}

function OpportunityDetail({item,saved,applied,onClose,onSave,onAction}:{item:Opportunity;saved:boolean;applied:boolean;onClose:()=>void;onSave:()=>void;onAction:(action:OpportunityAction)=>void}){
  const action=opportunityAction(item), locked=!canAccess(item);
  return <div className="modal-backdrop" onClick={onClose}><section className="detail-modal opportunity-detail" role="dialog" aria-modal="true" aria-label={item.title} onClick={e=>e.stopPropagation()}><button aria-label="Close" className="modal-close" onClick={onClose}><X/></button><div className="opp-detail-hero"><span><OpportunityIcon category={item.category}/></span><div><Badge gold={item.state==='Featured'||item.state==='Invitation'}>{item.state}</Badge><h2>{item.title}</h2><p>{item.description}</p></div><div className="detail-match"><b>{item.match}%</b><span>Match</span></div></div><div className="modal-meta detail-meta"><span><MapPin/>{item.location}</span><span><CalendarDays/>{item.date}</span><span><CircleDollarSign/>{item.compensation}</span><span><ShieldCheck/>{item.trust}</span></div><div className="opp-detail-grid"><section><h3>Opportunity Details</h3><dl><dt>Opportunity type</dt><dd>{item.category}</dd><dt>Organizer</dt><dd><Link href={organizerHref(item)}>{item.organization}</Link> · {item.organizerKind}</dd><dt>Access</dt><dd>{item.access}{locked?' · Upgrade required':''}</dd><dt>Application deadline</dt><dd>{item.deadline}</dd><dt>Availability</dt><dd>{item.slots}</dd><dt>Moderation state</dt><dd>{item.status}</dd></dl></section><section><h3>Why This Matches You</h3><div className="reason-list">{item.reasons.map(reason=><span key={reason}><Check/>{reason}</span>)}</div><blockquote>Strong alignment with your genre, location, live-performance goal, and current booking needs.</blockquote></section></div><div className="opp-detail-grid"><section><h3>Required Skills</h3><div className="detail-skills">{item.skills.map(skill=><span className={item.matchedSkills.includes(skill)?'matched':''} key={skill}>{item.matchedSkills.includes(skill)?<Check/>:<span/>}{skill}</span>)}</div><h3>Preferred Experience</h3><div className="detail-skills subtle">{item.preferred.map(x=><span key={x}>{x}</span>)}</div></section><section><h3>People You Should Connect With</h3>{item.relatedPeople.map((person,i)=><div className="opp-person-row" key={person}><Avatar initials={person.split(' ').map(x=>x[0]).join('').slice(0,2)} tone={i===0?'violet':i===1?'gold':'blue'}/><p><b>{person}</b><small>Why this person? Bridging-driven connection for this opportunity.</small></p><Link href={person.includes('Sarah')?'/profile/sarah-monroe':person.includes('Jessica')?'/profile/jessica-reed':person.includes('Marcus')?'/profile/marcus-lee':'/community'}>View</Link></div>)}</section></div><div className="opp-ecosystem"><div><span>Related Event</span><Link href="/events">{item.relatedEvent} <ArrowRight size={13}/></Link></div><div><span>Related Group</span><Link href={`/community/${item.relatedGroup==='Live Events & Touring'?'live-events-touring':item.relatedGroup==='Venues & Booking'?'venues-booking':item.relatedGroup==='Promotion & Marketing'?'promotion-marketing':'producers-engineers'}`}>{item.relatedGroup} <ArrowRight size={13}/></Link></div><div><span>FastTrack Relevance</span><Link href="/fasttrack">{item.fastTrack} <ArrowRight size={13}/></Link></div></div>{item.marketplaceServices.length>0&&<section className="opp-prep"><h3>Services that may help you prepare</h3><div>{item.marketplaceServices.map(service=><Link href="/marketplace?recommended=1" key={service}><Store size={14}/>{service}</Link>)}</div></section>}<div className="detail-actions"><button onClick={onSave}>{saved?<Check/>:<Bookmark/>}{saved?'Saved':'Save'}</button><button onClick={()=>{onClose();onAction('Share')}}><Share2/> Share</button><Link href={`/messages?provider=${encodeURIComponent(item.organization)}&listing=${encodeURIComponent(item.title)}&intent=Ask%20a%20Question`}>Message Organizer <ArrowRight size={14}/></Link><button className={locked?'locked-action':'primary-action'} onClick={()=>{onClose();onAction(locked?'Info':action.includes('Interest')?'Interest':action.includes('Introduction')?'Introduction':action.includes('Invitation')?'Invitation':action.includes('Info')?'Info':'Apply')}}>{applied?'Continue in Messages':action} <ArrowRight size={15}/></button></div></section></div>
}

function ConnectionButton({initial='Connect'}:{initial?:string}){
  const [state,setState]=useState(initial);
  if(state==='Accept') return <div className="request-actions"><button onClick={()=>setState('Connected')}><Check/>Accept</button><button onClick={()=>setState('Ignored')}>Ignore</button></div>;
  return <button className={state!=='Connect'?'connected':''} onClick={()=>setState(state==='Connect'?'Request Sent':'Connect')}>{state==='Connected'?<><Check/>Connected</>:state==='Request Sent'?<><Clock3/>Request Sent</>:state==='Ignored'?'Ignored':<>Connect<ArrowRight/></>}</button>;
}

